import {initReactBits} from './reactbits-adapted.js';
initReactBits();
const header=document.querySelector('.site-header'),hero=document.querySelector('.cinematic'),stage=document.querySelector('.scene-stage'),entry=document.querySelector('#entry-video'),exit=document.querySelector('#exit-video'),poster=document.querySelector('#scene-poster'),message=document.querySelector('.gold-message'),cue=document.querySelector('.discover-cue'),resume=document.querySelector('.video-resume');
const mobile=matchMedia('(max-width:760px)'),reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;
const clamp=v=>Math.max(0,Math.min(1,v)),smooth=v=>{v=clamp(v);return v*v*(3-2*v)};
let completed=false,hasScrolled=scrollY>2,headerTimer,raf=0,wanted=0,seeking=false,mediaFormat='';
function showHeader(immediate=false){if(immediate)header.classList.add('immediate');header.classList.add('visible');header.inert=false;}
function endEntry(){if(completed)return;completed=true;entry.pause();entry.classList.remove('active');poster.classList.add('active');cue.classList.add('visible');resume.classList.remove('visible');if(hasScrolled)showHeader(true);else headerTimer=setTimeout(()=>showHeader(),450);}
function seek(){if(!Number.isFinite(exit.duration)||exit.readyState<1||seeking)return;const goal=Math.min(wanted,exit.duration-1/30);if(Math.abs(exit.currentTime-goal)>.022){seeking=true;exit.currentTime=Math.max(0,goal);}}
exit.addEventListener('seeked',()=>{seeking=false;seek();});exit.addEventListener('loadeddata',()=>{seek();update();});exit.addEventListener('loadedmetadata',()=>{seeking=false;seek();});
function update(){raf=0;const rect=hero.getBoundingClientRect(),travel=hero.offsetHeight-stage.offsetHeight;const p=clamp(-rect.top/Math.max(1,travel));if(scrollY>2){hasScrolled=true;showHeader(true);if(!completed)endEntry();}const flow=clamp(p/.68),txt=smooth((p-.67)/.15);wanted=flow*5;
 if(p>.001&&completed&&!reduced){exit.classList.add('active');entry.classList.remove('active');seek();if(exit.readyState>=2)poster.classList.remove('active');}else if(completed){exit.classList.remove('active');poster.classList.add('active');}
 if(reduced&&p>.1){poster.src=`./assets/gold-${mediaFormat}.jpg`;poster.classList.add('active');}else if(reduced||p<=.001&&completed){poster.src=`./assets/unboxing-${mediaFormat}.jpg`;}
 message.style.opacity=String(reduced?(p>.3?1:0):txt);message.style.transform=`translateY(${(1-txt)*30}px)`;message.inert=reduced?p<=.3:txt<.5;message.setAttribute('aria-hidden',String(reduced?p<=.3:txt<.5));cue.classList.toggle('visible',completed&&p<.025);}
function queue(){if(!raf)raf=requestAnimationFrame(update);}
function loadMedia(){const next=mobile.matches?'portrait':'paysage';if(next===mediaFormat)return;mediaFormat=next;seeking=false;entry.poster=`./assets/unboxing-${next}.jpg`;entry.src=`./assets/entree-${next}.mp4`;exit.poster=`./assets/unboxing-${next}.jpg`;exit.src=`./assets/sortie-${next}.mp4`;poster.src=`./assets/unboxing-${next}.jpg`;entry.load();exit.load();if(reduced){hero.classList.add('reduced');endEntry();showHeader(true);}else if(!completed&&!hasScrolled){entry.classList.add('active');entry.play().catch(()=>{endEntry();resume.classList.add('visible');});}else{endEntry();queue();}}
entry.addEventListener('ended',endEntry);entry.addEventListener('error',()=>{endEntry();showHeader(true);});exit.addEventListener('error',()=>{exit.classList.remove('active');poster.src=`./assets/gold-${mediaFormat}.jpg`;poster.classList.add('active');});
resume.addEventListener('click',()=>{completed=false;poster.classList.remove('active');entry.classList.add('active');resume.classList.remove('visible');entry.currentTime=0;entry.play().catch(endEntry);});
window.addEventListener('scroll',queue,{passive:true});window.addEventListener('wheel',()=>{hasScrolled=true;showHeader(true);},{passive:true});window.addEventListener('touchmove',()=>{hasScrolled=true;showHeader(true);},{passive:true});window.addEventListener('resize',queue);mobile.addEventListener('change',loadMedia);document.addEventListener('keydown',e=>{if(['ArrowDown','PageDown','End',' '].includes(e.key)&&!['INPUT','TEXTAREA','BUTTON'].includes(document.activeElement.tagName)){hasScrolled=true;showHeader(true);}});
const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('.card-nav');function closeMenu(){toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Ouvrir le menu');nav.inert=true;nav.classList.remove('open');}toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Fermer le menu':'Ouvrir le menu');nav.inert=!open;nav.classList.toggle('open',open);});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();}});
document.querySelector('#appointment-form').addEventListener('submit',e=>{e.preventDefault();document.querySelector('#form-status').textContent='Cette version présente le formulaire. Pour convenir de votre rendez-vous, appelez le 04 66 52 10 00.';});document.querySelector('#current-year').textContent=new Date().getFullYear();
header.inert=true;loadMedia();if(hasScrolled){endEntry();showHeader(true);}update();
